import { test } from "node:test";
import assert from "node:assert/strict";
import shows from "./data/eastern-blok-shows.json" with { type: "json" };
import band from "./data/eastern-blok-press.json" with { type: "json" };

// eastern-blok-shows.json is generated by press/easternblok-shows.cjs from
// the Wayback copies of easternblok.net. These checks guard what the
// /easternblok page relies on, without needing the snapshots (they live
// outside git).

test("every show has a real date, a venue and a known status", () => {
	for (const show of shows.shows) {
		assert.match(show.date, /^\d{4}-\d{2}-\d{2}$/, JSON.stringify(show));
		assert.ok(!Number.isNaN(Date.parse(show.date)), show.date);
		assert.ok(show.venue, `${show.date} has no venue`);
		assert.ok(["past", "announced", "recorded"].includes(show.status), show.status);
		assert.ok(show.sources.length > 0);
	}
});

test("shows are in date order and span the band's years", () => {
	const dates = shows.shows.map((s) => s.date);
	assert.deepEqual(dates, [...dates].sort());
	assert.ok(dates[0].startsWith("2005"));
	assert.ok(dates.at(-1) <= "2012-12-31");
});

test("every recording link points at a known Internet Archive item", () => {
	const known = new Set(band.gigLog.shows.map((s) => s.archiveId));
	for (const show of shows.shows.filter((s) => s.recording)) {
		assert.ok(known.has(show.recording), show.recording);
	}
	assert.equal(shows.shows.filter((s) => s.recording).length, known.size);
});

test("every source snapshot is a Wayback URL for easternblok.net", () => {
	const ids = new Set(shows.sources.map((s) => s.id));
	for (const source of shows.sources) {
		assert.match(source.wayback, /^https:\/\/web\.archive\.org\/web\/\d{14}\/http:\/\/www\.easternblok\.net\//);
	}
	for (const show of shows.shows) {
		for (const id of show.sources) assert.ok(id === "internet-archive" || ids.has(id), id);
	}
});

test("shows marked 'with' a headliner say who, and each has a source in `confirmed`", () => {
	const withs = shows.shows.filter((s) => s.with);
	assert.ok(withs.length >= 10, "the Snarky Puppy dates are missing");
	for (const s of withs) {
		assert.equal(s.with, "Snarky Puppy");
		assert.ok(s.confirmed, `${s.date} ${s.venue} has no source`);
	}
});
